import * as THREE from 'three';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {RoomEnvironment} from 'three/addons/environments/RoomEnvironment.js';
const $=id=>document.getElementById(id);
import {exhibits,brands,resolveFinish} from './catalog.js';
let currentExhibit=exhibits[0],finish=exhibits[0].finishes[0],currentView='hero',scene,renderer,camera,controls,model,frame=0,sequence=0,transition=null,visible=true,ready=false,hasGL=false;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const loader=new GLTFLoader(),cache=new Map();
const desiredCamera=new THREE.Vector3();
function setStatus(text){$('load-progress').textContent=text;}
function setSource(){ $('source-note').textContent=currentExhibit.note;const link=$('source-panel').querySelector('a');link.href=currentExhibit.source;link.textContent='查看 '+currentExhibit.brandCN+' 官方资料 ↗';$('model-origin').textContent=currentExhibit.provenance;}
function fallbackImage(){return currentExhibit.brand==='Apple'?`./images/iphone-18-pro-${finish.id}.jpg`:currentExhibit.image;}
function renderSwatches(){ $('swatches').replaceChildren(...currentExhibit.finishes.map(f=>{const b=document.createElement('button');b.className='swatch';b.style.setProperty('--swatch',f.gradient?`linear-gradient(180deg,${f.gradient.join(',')})`:f.color);b.title=f.name;b.setAttribute('aria-label',f.name);b.setAttribute('aria-pressed',String(f.id===finish.id));b.addEventListener('click',()=>setFinish(f.id));return b;})); }
const gradientTextures=new Map();
function gradientTexture(f){if(gradientTextures.has(f.id))return gradientTextures.get(f.id);const canvas=document.createElement('canvas');canvas.width=4;canvas.height=256;const ctx=canvas.getContext('2d'),g=ctx.createLinearGradient(0,0,0,256);f.gradient.forEach((c,i)=>g.addColorStop(i/(f.gradient.length-1),c));ctx.fillStyle=g;ctx.fillRect(0,0,4,256);const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;texture.flipY=false;gradientTextures.set(f.id,texture);return texture;}
function setFinish(id){const f=currentExhibit.finishes.find(x=>x.id===id);if(!f)throw new Error('此机型没有该配色');finish=f;$('finish-name').textContent=f.name;renderSwatches();$('fallback-image').src=fallbackImage();$('fallback-image').alt=currentExhibit.title+' 外观参考（示意配色）';if(model&&model.userData.exhibitId===currentExhibit.id)model.traverse(o=>{if(!o.isMesh)return;for(const m of [o.material].flat()){if(!m.userData.originalColor)m.userData.originalColor=m.color.clone();if(m.userData.finish){if(f.original){m.color.copy(m.userData.originalColor);m.map=m.userData.originalMap??null;}else{m.color.set(f.color).multiplyScalar(m.userData.finishBrightness||.85);m.map=null;if(f.gradient&&m.name==='BodyFinish'){m.color.set(0xffffff);m.map=gradientTexture(f);}}m.needsUpdate=true;}}});}
function syncSelectors(){$('brand-tabs').replaceChildren(...brands.map(brand=>{const b=document.createElement('button');b.textContent=brand.name;b.setAttribute('aria-pressed',String(brand.id===currentExhibit.brand));b.addEventListener('click',()=>selectExhibit(exhibits.find(e=>e.brand===brand.id).id));return b;}));$('model-select').replaceChildren(...exhibits.filter(e=>e.brand===currentExhibit.brand).map(e=>{const o=document.createElement('option');o.value=e.id;o.textContent=e.title;o.selected=e.id===currentExhibit.id;return o;}));}
function setView(view,immediate=false){if(!['hero','front','back','camera','side'].includes(view))throw new Error('未知视角');currentView=view;document.querySelectorAll('[data-view]').forEach(b=>{const on=b.dataset.view===view;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);});if(!camera||!controls)return;controls.autoRotate=false;$('auto-rotate').setAttribute('aria-pressed','false');const mobile=innerWidth<650;const distance=mobile?9.5:8.5;const views={hero:[[3.6,1.65,-distance],[0,0,0]],front:[[0,.08,distance],[0,0,0]],back:[[0,.08,-distance],[0,0,0]],camera:[[-.68,1.55,-2.4],[-.35,1.12,-.05]],side:[[4.5,.35,-.9],[0,0,0]]};if(currentExhibit.brand!=='Apple')views.camera=[[.65,1.55,-2.7],[currentExhibit.brand==='Samsung'?.5:0,1.12,0]];const [pos,target]=views[view];if(immediate||reduced){camera.position.set(...pos);controls.target.set(...target);controls.update();transition=null;}else transition={from:camera.position.clone(),to:new THREE.Vector3(...pos),targetFrom:controls.target.clone(),targetTo:new THREE.Vector3(...target),start:performance.now()};}
function disposeModel(m){m.traverse(o=>{if(o.isMesh){o.geometry.dispose();for(const mat of [o.material].flat())mat.dispose();}});}
async function selectExhibit(id){const item=exhibits.find(e=>e.id===id);if(!item)throw new Error('未知藏品');const ticket=++sequence;currentExhibit=item;finish=resolveFinish(item,finish.id);ready=false;syncSelectors();setFinish(finish.id);$('current-model').textContent=item.title;document.title=item.title;document.querySelectorAll('.exhibit-card').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===id)));setSource();if(!hasGL)return;if(model){scene.remove(model);model=null;}$('loading').hidden=false;$('fallback').hidden=true;setStatus('加载精细模型…');try{let pending=cache.get(id);if(!pending){pending=loader.loadAsync(item.model,p=>{if(ticket===sequence)setStatus(p.total?`模型已加载 ${Math.round(p.loaded/p.total*100)}%`:'正在加载精细模型…');});cache.set(id,pending);pending.catch(()=>cache.delete(id));}const gltf=await pending;if(ticket!==sequence)return;if(model)scene.remove(model);model=gltf.scene;const box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3());if(!model.userData.normalized){const center=box.getCenter(new THREE.Vector3());model.position.sub(center);const wrapper=new THREE.Group();wrapper.add(model);wrapper.scale.setScalar(4.35/size.y);model=wrapper;model.userData.normalized=true;gltf.scene=wrapper;}model.userData.exhibitId=id;scene.add(model);model.traverse(o=>{if(o.isMesh){for(const m of [o.material].flat()){if(m.map&&m.userData.originalMap===undefined)m.userData.originalMap=m.map;for(const key of ['map','normalMap','roughnessMap','metalnessMap'])if(m[key])m[key].anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());m.envMapIntensity=1.15;if(m.name.toLowerCase().includes('screen')){m.toneMapped=false;}}}});setFinish(finish.id);setView('hero',true);ready=true;$('loading').hidden=true;}catch(e){console.error(e);if(ticket===sequence)showFallback('模型暂时无法加载，请重试');}}
function showFallback(text){$('loading').hidden=true;$('fallback').hidden=false;$('fallback').querySelector('p').textContent=text;$('fallback-image').src=fallbackImage();}
function resize(){if(!renderer)return;const rect=$('viewport').getBoundingClientRect();if(rect.width<1||rect.height<1)return;renderer.setSize(rect.width,rect.height);camera.aspect=rect.width/rect.height;camera.fov=innerWidth<650?36:32;camera.setViewOffset(rect.width,rect.height,0,0,rect.width,rect.height);camera.updateProjectionMatrix();}
function animate(now){frame=0;if(!visible)return;if(transition){const p=Math.min((now-transition.start)/750,1),t=p*p*(3-2*p);camera.position.lerpVectors(transition.from,transition.to,t);controls.target.lerpVectors(transition.targetFrom,transition.targetTo,t);if(p===1)transition=null;}controls.update();renderer.render(scene,camera);frame=requestAnimationFrame(animate);}
try{scene=new THREE.Scene();renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.setClearColor(0xffffff,0);renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;renderer.outputColorSpace=THREE.SRGBColorSpace;$('viewport').append(renderer.domElement);camera=new THREE.PerspectiveCamera(32,1,.02,100);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=!reduced;controls.dampingFactor=.08;controls.enablePan=false;controls.minDistance=1.7;controls.maxDistance=14;controls.autoRotateSpeed=.65;controls.addEventListener('start',()=>{transition=null;});const room=new RoomEnvironment(),pmrem=new THREE.PMREMGenerator(renderer);scene.environment=pmrem.fromScene(room,.035).texture;room.dispose();pmrem.dispose();scene.add(new THREE.HemisphereLight(0xffffff,0x777a91,.8));const key=new THREE.DirectionalLight(0xfff2df,2.5);key.position.set(-5,8,-6);scene.add(key);const rim=new THREE.DirectionalLight(0xd2e2ff,2);rim.position.set(6,3,5);scene.add(rim);hasGL=true;new ResizeObserver(resize).observe($('viewport'));resize();frame=requestAnimationFrame(animate);renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();visible=false;showFallback('3D 展示已中断，请重新加载');});}catch(e){console.error(e);showFallback('当前设备无法启动 3D 展示，请开启硬件加速或更换浏览器');}
document.addEventListener('visibilitychange',()=>{visible=!document.hidden;if(visible&&hasGL&&!frame)frame=requestAnimationFrame(animate);});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
$('auto-rotate').addEventListener('click',()=>{if(!controls)return;transition=null;controls.autoRotate=!controls.autoRotate;$('auto-rotate').setAttribute('aria-pressed',String(controls.autoRotate));});$('reset').addEventListener('click',()=>setView('hero'));$('retry').addEventListener('click',()=>location.reload());$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.gallery').requestFullscreen();}catch{ $('fullscreen').title='当前浏览器不支持全屏'; }});
$('collection-toggle').addEventListener('click',()=>{const open=$('collection-panel').hidden;$('collection-panel').hidden=!open;$('collection-toggle').setAttribute('aria-expanded',String(open));if(open)$('collection-panel').scrollIntoView({behavior:reduced?'instant':'smooth',block:'end'});});
$('source-toggle').addEventListener('click',()=>{const open=$('source-panel').hidden;$('source-panel').hidden=!open;$('source-toggle').setAttribute('aria-expanded',String(open));if(open)$('source-panel').scrollIntoView({behavior:reduced?'instant':'smooth',block:'end'});});
$('exhibit-list').replaceChildren(...exhibits.map(e=>{const b=document.createElement('button');b.className='exhibit-card';b.dataset.id=e.id;b.setAttribute('aria-pressed',String(e.id===currentExhibit.id));b.innerHTML=`<small>${e.brand.toUpperCase()} · ${e.year} / ${e.number}</small>${e.title} <span>${e.provenance} · ${e.finishes.length} 款配色 ↗</span>`;b.addEventListener('click',async()=>{await selectExhibit(e.id);window.scrollTo({top:0,behavior:reduced?'instant':'smooth'});});return b;}));
$('model-select').addEventListener('change',e=>selectExhibit(e.target.value));
renderSwatches();setSource();selectExhibit(currentExhibit.id);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_exhibit',title:'切换手机藏品与配色',description:'选择手机、配色和观察视角。',inputSchema:{type:'object',properties:{exhibit:{type:'string',enum:exhibits.map(e=>e.id)},finish:{type:'string',enum:[...new Set(exhibits.flatMap(e=>e.finishes.map(f=>f.id)))]},view:{type:'string',enum:['hero','front','back','camera','side']}},additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['exhibit','finish','view'].includes(k))||input.exhibit&&!exhibits.some(e=>e.id===input.exhibit)||input.finish&&!(exhibits.find(e=>e.id===input.exhibit)||currentExhibit).finishes.some(f=>f.id===input.finish)||input.view&&!['hero','front','back','camera','side'].includes(input.view))throw new Error('请选择有效的藏品、配色与视角');if(input.exhibit)await selectExhibit(input.exhibit);if(input.finish)setFinish(input.finish);if(input.view)setView(input.view,true);return {exhibit:currentExhibit.id,finish:finish.id,view:currentView,modelLoaded:ready};}})).catch(()=>{});}catch{}}
